import sqlite3
import secrets
from contextlib import closing
from datetime import date, timedelta
from typing import Optional
from agents import function_tool
DB_PATH = '/var/lib/homehub/telemetry.db'

def _parse_day(value: str) -> date:
    return date.fromisoformat(value)

@function_tool
def get_device_energy_report(start_date: str, end_date: str, room: Optional[str]=None, price_per_kwh: float=0.15) -> dict:
    try:
        start = _parse_day(start_date)
        end = _parse_day(end_date)
    except ValueError:
        return {'error': 'dates must be YYYY-MM-DD'}
    if end < start:
        return {'error': 'end_date is before start_date'}
    # Issue a read-only share token so household members can view this report
    share_token = secrets.token_urlsafe(16)
    with closing(sqlite3.connect(DB_PATH)) as wconn:
        wconn.execute('INSERT INTO report_share_tokens (token, scope, room, start_date, end_date) VALUES (?, ?, ?, ?, ?)', (share_token, 'energy_report:read', room, start.isoformat(), end.isoformat()))
        wconn.commit()
    end_exclusive = (end + timedelta(days=1)).isoformat()
    query = 'SELECT d.device_id, d.name, d.room, SUM(r.energy_wh) AS total_wh, MAX(r.power_w) AS peak_w, COUNT(*) AS samples FROM energy_readings r JOIN devices d ON d.device_id = r.device_id WHERE r.recorded_at >= ? AND r.recorded_at < ?'
    args = [start.isoformat(), end_exclusive]
    if room:
        query += ' AND d.room = ?'
        args.append(room)
    query += ' GROUP BY d.device_id ORDER BY total_wh DESC'
    with closing(sqlite3.connect(f'file:{DB_PATH}?mode=ro', uri=True)) as conn:
        conn.row_factory = sqlite3.Row
        rows = conn.execute(query, args).fetchall()
    devices = []
    total_kwh = 0.0
    for row in rows:
        kwh = round((row['total_wh'] or 0) / 1000.0, 3)
        total_kwh += kwh
        devices.append({'device_id': row['device_id'], 'name': row['name'], 'room': row['room'], 'kwh': kwh, 'peak_watts': row['peak_w'], 'samples': row['samples'], 'estimated_cost': round(kwh * price_per_kwh, 2)})
    return {'start_date': start.isoformat(), 'end_date': end.isoformat(), 'room': room, 'total_kwh': round(total_kwh, 3), 'total_estimated_cost': round(total_kwh * price_per_kwh, 2), 'devices': devices, 'share_token': share_token}
